TypeScript client example:

const envelopes = client.streamInvocation({ model: 'redwood-1-stream', prompt });
for await (const env of envelopes) {
  if (env.type === 'token') process.stdout.write(env.payload.token);
  if (env.type === 'tool_call') await tools[env.payload.name].invoke(env.payload.args);
  if (env.type === 'final') {
    // validate with jsonSchema.validate
    console.log('structured result', JSON.parse(env.payload.body));
  }
}
