Go client example:

ch := client.StreamInvocation(ctx, opts)
for env := range ch {
    switch env.Type {
    case "token": os.Stdout.Write([]byte(env.Payload.Token))
    case "tool_call": tools[env.Payload.Name].Invoke(ctx, env.Payload.Args)
    case "final": var out MyStructuredType; json.Unmarshal([]byte(env.Payload.Body), &out); fmt.Printf("result %+v", out)
    }
}
